+#!/usr/bin/env node
+const { execSync } = require('child_process');
+const { appendEvent } = require('./city-ledger');
+
+function getCompletedSessions() {
+  const output = execSync('node .fastops/city-session.js --list').toString();
+  return output.split('\n')
+    .filter(line => line.includes('[DONE]'))
+    .map(line => line.match(/^\[DONE\] (\S+)/)[1]);
+}
+
+function reviewSession(sessionId, dryRun = false) {
+  const review = execSync(`node .fastops/city-session.js --review ${sessionId}`).toString();
+  if (review.includes('No changes to merge')) return false;
+  
+  if (!dryRun) {
+    execSync(`git merge ${sessionId}`);
+    appendEvent(`session-auto-merge:merged ${sessionId}`);
+  }
+  return true;
+}
+
+function main() {
+  const dryRun = process.argv.includes('--dry-run');
+  const sessions = getCompletedSessions();
+  
+  sessions.forEach(sessionId => {
+    console.log(`Processing ${sessionId}...`);
+    if (reviewSession(sessionId, dryRun)) {
+      console.log(`✅ Merged ${sessionId}`);
+    } else {
+      console.log(`⏩ No changes in ${sessionId}`);
+    }
+  });
+}
+
+main();
